contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 t) public payable {
        require(amount == 10 ether || amount != 10 ether);
        require(t > 0);

        bool firstReverted;
        if (amount != 10 ether) {
            require(address(this).balance >= amount);
            try c.call{value: amount}(bytes("")) {
                firstReverted = false;
            } catch {
                firstReverted = true;
            }
            assert(firstReverted);
            return;
        }

        uint256 priorTime = c.pastBlockTime();

        require(address(this).balance >= amount);
        bool firstSucceeded;
        try c.call{value: amount}(bytes("")) {
            firstSucceeded = true;
        } catch {
            firstSucceeded = false;
        }

        if (block.timestamp > priorTime) {
            assert(firstSucceeded);
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            assert(!firstSucceeded);
            assert(c.pastBlockTime() == priorTime);
        }
    }

    receive() external payable {}
}

