contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint112 burn, bool useFastTime) public payable {
        uint amount = 10 ether;
        require(address(this).balance >= amount);

        // Make the current time different from c's stored pastBlockTime, if possible.
        uint t = c.pastBlockTime();
        uint newTime = useFastTime ? t + 2 : t + 1;
        require(newTime > block.timestamp);
        uint delta = newTime - block.timestamp;
        // warp time by calling a benign function? There is none. Use a view-only call to check time.
        // We cannot warp block.timestamp; instead, only proceed if the next block.timestamp will naturally advance,
        // but we cannot control that here. Use a benign call? None. So only test first-call cases or rely on pastBlockTime update.

