        uint beforeThis = address(this).balance;
        uint beforePast = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(c).balance == beforeC + amount);
            assert(c.pastBlockTime() == block.timestamp);
            assert(c.pastBlockTime() > beforePast);
        }
    }

