            // the whole test reverts, so we guard with a check that it will succeed.
            // The only condition for success is block.timestamp > c.pastBlockTime().
            // We can check that before making the call.
            require(block.timestamp > c.pastBlockTime(), "cannot set up: timestamp not increasing");
            // Ensure this contract has 10 ether to send.
            require(address(this).balance >= 10 ether, "need 10 ether for setup");
            // Make the setup call as its own statement.
            (bool setupOk, ) = address(c).call{value: 10 ether}("");
            require(setupOk, "setup call failed");
        }

        uint beforeBalance = address(c).balance;
        uint beforePastBlockTime = c.pastBlockTime();

        // Record whether the gas left is sufficient? Not needed.
        // Make the deciding call as its own top-level statement.
        (bool success, ) = address(c).call{value: amount}("");
        bool reverted = !success;

