        require(msg.value >= sendAmount + setupAmount);

        // Optionally pre-seed c with some value from this test, and record it.
        // We cannot predict whether the initial fresh c has zero balance, but
        // setupAmount lets us add value without affecting the invariant's intent.
        if (setupAmount > 0) {
            (bool setupOk, ) = address(c).call{value: setupAmount}("");
            setupOk;
        }

        uint oldPastBlockTime = c.pastBlockTime();
        uint oldThisBalance = address(this).balance;
        uint amountToSend = 10 ether;
        require(address(this).balance >= amountToSend);

        bool reverted;
        try c.call{value: amountToSend}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint newPastBlockTime = c.pastBlockTime();
        uint newThisBalance = address(this).balance;

        assert(!reverted
            ? (newPastBlockTime > oldPastBlockTime
               && oldThisBalance - newThisBalance == amountToSend
               && (block.number % 15 == 0
                   ? address(c).balance == 0
                   : address(c).balance == sendAmount + setupAmount + amountToSend))
            : (newPastBlockTime == oldPastBlockTime
               && newThisBalance == oldThisBalance));
    }
    receive() external payable {}
}

